// F1-06zu (D10-284): the planned operationId list is generated by `pnpm codegen` from the
// `x-implementation: planned` marks of contracts/openapi.yaml. Expectations are read from the
// contract itself, never a hand-written list, so they follow the contract when a route ships.
import { spawnSync } from 'node:child_process';
import { existsSync } from 'node:fs';
import { cp, mkdir, mkdtemp, readFile, rm, symlink, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { expect, it } from 'vitest';
import {
  GENERATED,
  OPENAPI,
  generatedExports,
  plannedOf,
  repoPath,
  requiredText,
  stringLists,
} from './contract.ts';

const CODEGEN_TIMEOUT = 400_000;

/** The generated list(s) of a source text: at least one, each equal to the contract's marks. */
function listsOf(source: string): string[][] {
  const lists = stringLists(generatedExports(source));
  expect(lists, 'the generated file exports the planned operationIds').not.toEqual([]);
  return lists;
}

it('[AC-F1-06zu-GEN#1] 生成文件导出的清单与 openapi.yaml 当前 planned 标记逐个一致，且带生成文件头', () => {
  const expected = plannedOf(requiredText(OPENAPI));
  expect(expected.length).toBeGreaterThan(0);
  const source = requiredText(GENERATED);
  expect(source.startsWith('// GENERATED FILE. Do not edit by hand.')).toBe(true);
  expect(source).toContain('contracts/openapi.yaml');
  for (const list of listsOf(source)) expect(list).toEqual(expected);
});

/** A copy of what codegen reads, under the git-ignored .tmp/, with its own contracts/. */
async function fixture(): Promise<string> {
  requiredText(OPENAPI);
  expect(existsSync(repoPath('packages/contracts-ts/node_modules')), 'contracts-ts deps').toBe(
    true,
  );
  const parent = repoPath('.tmp/F1-06zu/');
  await mkdir(parent, { recursive: true });
  const root = await mkdtemp(join(parent, 'codegen-'));
  try {
    const pkg = join(root, 'packages/contracts-ts');
    await cp(repoPath('packages/contracts-ts/scripts'), join(pkg, 'scripts'), { recursive: true });
    await cp(repoPath('packages/contracts-ts/package.json'), join(pkg, 'package.json'));
    await mkdir(join(pkg, 'src'), { recursive: true });
    // Dependencies only (openapi-typescript); the scripts themselves are copies, so their paths
    // resolve inside the copy and nothing is written to the work tree.
    await symlink(repoPath('packages/contracts-ts/node_modules'), join(pkg, 'node_modules'), 'dir');
    await cp(repoPath('contracts'), join(root, 'contracts'), { recursive: true });
    await cp(repoPath('specs'), join(root, 'specs'), { recursive: true });
    await cp(repoPath('tools/lib'), join(root, 'tools/lib'), { recursive: true });
    await writeFile(join(root, 'package.json'), '{"type":"module"}\n');
    return root;
  } catch (error) {
    await rm(root, { recursive: true, force: true });
    throw error;
  }
}

function codegen(root: string, check: boolean): { status: number | null; stderr: string } {
  const child = spawnSync(
    process.execPath,
    [join(root, 'packages/contracts-ts/scripts/codegen.ts'), ...(check ? ['--check'] : [])],
    { cwd: root, encoding: 'utf8', timeout: 120_000 },
  );
  expect(child.error, child.stderr).toBeUndefined();
  expect(child.signal, child.stderr).toBeNull();
  expect(child.status, child.stderr).not.toBeNull();
  return { status: child.status, stderr: child.stderr };
}

/** Drops the `x-implementation: planned` line of one operation (its own indentation only). */
function withoutPlanned(source: string, operationId: string): string {
  const lines = source.split('\n');
  const indent = (line: string): number => line.length - line.trimStart().length;
  const at = lines.findIndex((line) => line.trim() === `operationId: ${operationId}`);
  expect(at, `operationId ${operationId} in openapi.yaml`).toBeGreaterThanOrEqual(0);
  const depth = indent(lines[at]!);
  let start = at;
  while (start > 0 && (lines[start - 1]!.trim() === '' || indent(lines[start - 1]!) >= depth))
    start -= 1;
  let end = at + 1;
  while (end < lines.length && (lines[end]!.trim() === '' || indent(lines[end]!) >= depth))
    end += 1;
  const marks: number[] = [];
  for (let index = start; index < end; index += 1) {
    const line = lines[index]!;
    if (indent(line) === depth && line.trim() === 'x-implementation: planned') marks.push(index);
  }
  expect(marks, `one planned mark on ${operationId}`).toHaveLength(1);
  return lines.filter((_, index) => index !== marks[0]).join('\n');
}

it(
  '[AC-F1-06zu-GEN#2] 临时副本里去掉一个 planned 标记：--check 报清单漂移，重新生成后该操作不在清单、其余照旧',
  async () => {
    const contract = requiredText(OPENAPI);
    const expected = plannedOf(contract);
    expect(expected.length).toBeGreaterThan(1);
    const root = await fixture();
    try {
      const output = join(root, 'packages/contracts-ts/src/planned-operations.gen.ts');
      // The unchanged contract regenerates exactly the committed file.
      expect(codegen(root, false).status).toBe(0);
      expect(existsSync(output), 'codegen writes src/planned-operations.gen.ts').toBe(true);
      const fresh = await readFile(output, 'utf8');
      expect(fresh).toBe(requiredText(GENERATED));
      for (const list of listsOf(fresh)) expect(list).toEqual(expected);

      // The route ships: its planned mark goes away.
      const target = expected[0]!;
      const shipped = withoutPlanned(contract, target);
      expect(plannedOf(shipped)).toEqual(expected.filter((id) => id !== target));
      await writeFile(join(root, OPENAPI), shipped);

      const stale = codegen(root, true);
      expect(stale.status).not.toBe(0);
      expect(stale.stderr).toContain('planned-operations.gen.ts');
      expect(await readFile(output, 'utf8')).toBe(fresh);

      expect(codegen(root, false).status).toBe(0);
      const regenerated = await readFile(output, 'utf8');
      for (const list of listsOf(regenerated)) {
        expect(list).not.toContain(target);
        expect(list).toEqual(expected.filter((id) => id !== target));
      }
      expect(codegen(root, true).status).toBe(0);
    } finally {
      await rm(root, { recursive: true, force: true });
    }
  },
  CODEGEN_TIMEOUT,
);
